function canAdvanceToPhase1(state) {
    const blockers = [];
    // 快速启动模式降低对话轮次要求
    const minMessages = state.entryMode === 'quick_start' ? 2 : 6;
    if (state.messages.length < minMessages) {
        blockers.push(`对话轮次不足——${state.entryMode === 'quick_start' ? '快速启动仅需用户确认' : `至少需要 ${minMessages / 2} 轮对话`}`);
    }
    if (!state.painPointsRaw || state.painPointsRaw.length < 10) {
        // 快速启动：预填范围可替代痛点描述
        if (state.entryMode !== 'quick_start' || !state.concernedDimensions) {
            blockers.push('尚未充分了解用户痛点');
        }
    }
    if (!state.concernedDimensions || state.concernedDimensions.length < 2) {
        blockers.push('关注的维度不足——至少需要 2 个');
    }
    if (!state.depth) {
        blockers.push('尚未确认诊断深度');
    }
    return {
        canAdvance: blockers.length === 0,
        blockers,
    };
}
